INSERT INTO `certifications` (`id`, `name`, `category`, `certificate_number`, `issued_by`, `valid_until`, `description`, `image`, `status`, `sort_order`, `created_at`) VALUES
	(1, 'IATF 16949:2016', 'Automotive Quality Management', 'IATF-0482910 / TÜV-CERT', 'TÜV Rheinland International', '2027-12-31', 'Standar sistem manajemen mutu tertinggi dan wajib bagi rantai pasok otomotif global (Tier-1 Supplier) untuk desain, rekayasa, dan manufaktur roda kemudi, airbag, dan modul resin interior.', 'uploads/certifications/cert_iatf_16949.svg', 'active', 1, '2026-10-14 07:14:13'),
	(2, 'ISO 9001:2015', 'Quality Management System', 'ID-QMS-9001-88321', 'SGS International Certification', '2028-06-30', 'Sertifikasi sistem manajemen mutu internasional yang memastikan konsistensi proses operasional, ketertelusuran material (traceability), dan kepuasan pelanggan secara berkesinambungan.', 'uploads/certifications/cert_iso_9001.svg', 'active', 2, '2026-10-14 07:14:13'),
	(3, 'ISO 14001:2015', 'Environmental Management System', 'EMS-14001-ID-54210', 'Lloyd\'s Register / SGS', '2027-10-15', 'Sistem manajemen lingkungan sesuai regulasi Kementerian Lingkungan Hidup dan Kehutanan (KLHK) RI, pengelolaan limbah B3 berizin, efisiensi energi, dan program reduksi jejak karbon pabrik.', 'uploads/certifications/cert_iso_14001.svg', 'active', 3, '2026-10-14 07:14:13'),
	(4, 'ISO 45001:2018 & SMK3 PP 50/2012', 'Occupational Health & Safety (K3)', 'OHSMS-45001-SMK3-9921', 'Kementerian Ketenagakerjaan RI & TÜV Rheinland', '2027-08-20', 'Penerapan Sistem Manajemen Keselamatan dan Kesehatan Kerja (SMK3) sesuai Peraturan Pemerintah RI No. 50 Tahun 2012 dan ISO 45001 guna menjamin budaya keselamatan kerja tanpa kecelakaan (Zero Accident).', 'uploads/certifications/cert_iso_45001.svg', 'active', 4, '2026-10-14 07:14:13'),
	(5, 'Kemenperin & SNI Compliance', 'National Regulatory Standards', 'REG-KEMENPERIN-TKDN-2026', 'Kementerian Perindustrian Republik Indonesia', '2029-01-01', 'Kepatuhan terhadap standar keselamatan komponen kendaraan bermotor nasional dan pemenuhan Tingkat Komponen Dalam Negeri (TKDN) sesuai peta jalan industri manufaktur Kemenperin RI.', 'uploads/certifications/cert_tkdn_kemenperin.svg', 'active', 5, '2026-10-14 07:14:13');
INSERT INTO `company_profile` (`id`, `company_name`, `tagline`, `short_description`, `about_text`, `vision`, `mission`, `values_text`, `address`, `phone`, `email`, `logo`, `updated_at`) VALUES
	(1, 'PT Nihon Plast Indonesia', 'Driving Safety & Precision Through Japanese Monozukuri', 'Tier-1 Global Automotive Supplier berspesialisasi dalam Roda Kemudi (Steering Wheels), Modul Airbag, dan Komponen Plastik Resin Interior-Eksterior dengan standar sertifikasi IATF 16949, ISO 14001, dan ISO 45001.', 'PT Nihon Plast Indonesia merupakan anak perusahaan dari Nihon Plast Co., Ltd. (Jepang) yang didirikan untuk menghadirkan keunggulan manufaktur komponen otomotif kelas dunia di Indonesia. Berlokasi strategis di Kawasan Industri Indotaisei Cikampek, Karawang, fasilitas manufaktur kami mengintegrasikan teknologi injeksi plastik presisi (Precision Resin Molding berkapasitas 150T hingga 2500T), keahlian pembungkusan kulit premium (Genuine Leather & Synthetic Wrapping Craftsmanship), perakitan modul keselamatan airbag di Cleanroom Class 8 berstandar global, serta laboratorium pengujian kualitas ketat demi memenuhi standar OEM Tier-1 internasional dan regulasi industri Republik Indonesia (TKDN, IATF 16949, ISO 14001, dan SMK3 PP 50/2012).', 'Menjadi mitra manufaktur otomotif \'One-of-a-Kind\' yang tak tergantikan bagi pelanggan melalui penguasaan teknologi unik, dedikasi keselamatan tanpa kompromi, dan produk berkualitas tinggi.', '1. Menghasilkan produk otomotif yang membanggakan serta memenuhi standar mutu internasional tertinggi (IATF 16949:2016).\n2. Menjalankan filosofi Monozukuri dan Kaizen secara konsisten di seluruh lini operasional.\n3. Mematuhi regulasi ketenagakerjaan, keselamatan kerja (SMK3/ISO 45001), dan kepedulian lingkungan (ISO 14001) demi pembangunan industri nasional yang berkelanjutan.', 'Monozukuri (Craftsmanship), Safety First, Integrity, Continuous Improvement (Kaizen), and Sustainable Harmony.', 'Kawasan Industri Indotaisei Sektor 1A Blok B-3, Desa Kalihurip, Kec. Cikampek, Kab. Karawang, Jawa Barat 41373, Indonesia', '+62 (264) 351-470 / +62 (264) 351-471', 'info@n-plast.co.id', 'logo_nihon_plast_green.png', '2026-10-14 07:40:26');
INSERT INTO `content_translations` (`id`, `entity_type`, `entity_id`, `lang_code`, `field_name`, `translation_value`, `created_at`, `updated_at`) VALUES
	(1, 'product', 1, 'en', 'name', 'Steering Wheel Systems', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(2, 'product', 1, 'en', 'description', 'Global-standard steering wheel systems featuring high-precision genuine leather wrapping, premium polyurethane formulations, multifunction control switches, integrated heating elements, and Hands-on Detection (HOD) safety touch sensors.', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(3, 'product', 1, 'ja', 'name', 'ステアリングホイールシステム', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(4, 'product', 1, 'ja', 'description', '高精度本革巻き、高品質ポリウレタン成形、マルチファンクション制御スイッチ、ステアリングヒーター、およびハンズオン検知（HOD）安全タッチセンサーを統合した世界標準のステアリングホイールシステム。', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(5, 'product', 1, 'zh', 'name', '方向盘安全集成系统', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(6, 'product', 1, 'zh', 'description', '符合全球标准的汽车方向盘系统，采用高精度真皮包覆、优质聚氨酯成型工艺、集成多功能控制按键、方向盘加热元件及脱手检测（HOD）安全传感技术。', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(7, 'product', 1, 'ko', 'name', '스티어링 휠 안전 시스템', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(8, 'product', 1, 'ko', 'description', '고정밀 천연 가죽 래핑, 프리미엄 폴리우레탄 폼 성형, 다기능 스위치 모듈, 열선 스티어링 휠 및 핸즈온 감지(HOD) 안전 센서를 결합한 글로벌 스탠다드 조향 시스템.', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(9, 'product', 2, 'en', 'name', 'Airbag Safety Modules', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(10, 'product', 2, 'en', 'description', 'Integrated high-speed airbag modules (Driver, Passenger, Side Curtain, and Knee Airbag) engineered with precision tear-seam resin covers that deploy flawlessly within milliseconds upon collision impact.', '2026-10-16 01:34:46', '2026-10-16 01:34:46'),
	(11, 'product', 2, 'ja', 'name', 'エアバッグ安全モジュール', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(12, 'product', 2, 'ja', 'description', '衝突時にミリ秒単位で完璧に展開する高精度テアシーム樹脂カバーを備えた統合型高速エアバッグモジュール（運転席、助手席、サイドカーテン、およびニーエアバッグ）。', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(13, 'product', 2, 'zh', 'name', '安全气囊防护模块', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(14, 'product', 2, 'zh', 'description', '一体化高速安全气囊模块（驾驶员、副驾驶、侧气帘及膝部气囊），配备精密弱化线树脂气囊罩，确保在碰撞瞬间毫秒级精准爆破展开，全方位守护乘员安全。', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(15, 'product', 2, 'ko', 'name', '에어백 안전 모듈 시스템', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(16, 'product', 2, 'ko', 'description', '충돌 시 수 밀리초 내에 오차 없이 완벽하게 전개되는 정밀 티어 심(tear-seam) 레진 커버를 적용한 통합 고속 에어백 모듈(운전석, 동승석, 사이드 커튼 및 무릎 에어백).', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(17, 'product', 3, 'en', 'name', 'Cockpit & Interior Resin Parts', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(18, 'product', 3, 'en', 'description', 'High-aesthetic, millimeter-precision cockpit interior resin components: Instrument Panel Clusters, Air Conditioner Registers & Ducts, Center Console Boxes, Glove Boxes, Cup Holders, and Pillar Garnishes.', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(19, 'product', 3, 'ja', 'name', 'コックピット・インストルメントパネル内装樹脂部品', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(20, 'product', 3, 'ja', 'description', '高品位な意匠性とミリ単位の精度を誇るキャビン内装樹脂部品：インストルメントパネル、エアコン吹出口・レジスター、センターコンソールボックス、グローブボックス、カップホルダー、ピラーガーニッシュ。', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(21, 'product', 3, 'zh', 'name', '座舱仪表板及内饰树脂零件', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(22, 'product', 3, 'zh', 'description', '兼具卓越美学质感与毫米级装配精度的汽车座舱内饰件：仪表板总成、空调出风口与风道系统、中央扶手箱、手套箱、杯托总成以及立柱护板饰条。', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(23, 'product', 3, 'ko', 'name', '콕핏 및 인테리어 레진 정밀 부품', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(24, 'product', 3, 'ko', 'description', '뛰어난 감성 품질과 밀리미터 단위 정밀도를 갖춘 콕핏 인테리어 플라스틱 부품: 인스트루먼트 패널 클러스터, 공조 에어벤트 레지스터 및 덕트, 센터 콘솔 박스, 글로브 박스, 컵홀더, 필러 가니시.', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(25, 'product', 4, 'en', 'name', 'Exterior & Aerodynamic Trim', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(26, 'product', 4, 'en', 'description', 'Rugged exterior resin components with high resistance against extreme weather conditions and stone chipping: Cowl Top Covers, Fender Protectors, and Noise-Damping Wheel Resonators for superior acoustic comfort.', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(27, 'product', 4, 'ja', 'name', '外装・エアロダイナミックトリム部品', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(28, 'product', 4, 'ja', 'description', '過酷な耐候性と耐チッピング性を備えた高強度外装樹脂部品：カウルトップカバー、フェンダープロテクター、およびロードノイズを低減するホイールレゾネーター。', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(29, 'product', 4, 'zh', 'name', '外饰及空气动力学组件', '2026-10-16 01:34:47', '2026-10-16 01:34:47'),
	(30, 'product', 4, 'zh', 'description', '具备优异耐候性与抗飞石冲击性能的高强度外饰树脂组件：风挡集雨板总成（Cowl Top）、翼子板护板以及有效降低轮胎腔体共鸣噪音的轮毂消音器（Wheel Resonator）。', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(31, 'product', 4, 'ko', 'name', '익스테리어 및 공기역학 트림 부품', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(32, 'product', 4, 'ko', 'description', '극한의 기후 조건과 주행 중 스톤칩에 견디는 고내구성 외장 부품: 카울 탑 커버, 펜더 프로텍터 및 주행 소음을 획기적으로 흡수하는 휠 레조네이터.', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(33, 'company_profile', 1, 'en', 'tagline', 'Driving Safety & Precision Through Japanese Monozukuri', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(34, 'company_profile', 1, 'en', 'short_description', 'Tier-1 Global Automotive Supplier specializing in Steering Wheels, Airbag Modules, and Interior/Exterior Resin Components certified to IATF 16949, ISO 14001, and ISO 45001 standards.', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(35, 'company_profile', 1, 'en', 'about_text', 'PT Nihon Plast Indonesia is a premier Tier-1 global automotive supplier established in Karawang, West Java. Backed by Nihon Plast Co., Ltd. (Japan) since 1948, we manufacture safety-critical steering wheels, airbag systems, and high-precision resin components for leading global OEMs.', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(36, 'company_profile', 1, 'en', 'vision', 'To be the most trusted Tier-1 automotive safety and precision component partner worldwide, championing Japanese Monozukuri craftsmanship, zero-defect quality, and sustainable manufacturing.', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(37, 'company_profile', 1, 'en', 'mission', 'Deliver unmatched automotive occupant safety and interior refinement through cutting-edge technology, stringent quality management, empowerment of human talent, and environmental responsibility.', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(38, 'company_profile', 1, 'ja', 'tagline', '日本のモノづくりで創る、自動車の安全と極限の精密さ', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(39, 'company_profile', 1, 'ja', 'short_description', 'IATF 16949、ISO 14001、ISO 45001認証を取得した、ステアリングホイール、エアバッグモジュール、内外装樹脂部品を専門とするグローバルTier-1自動車部品メーカー。', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(40, 'company_profile', 1, 'ja', 'about_text', 'PT Nihon Plast Indonesiaは、西ジャワ州カラワンに拠点を置く世界有数のTier-1自動車サプライヤーです。1948年創業の日本プラスト株式会社のDNAを受け継ぎ、世界的な自動車メーカー（OEM）向けにステアリング、エアバッグ、高精度樹脂部品を製造しています。', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(41, 'company_profile', 1, 'ja', 'vision', '日本のモノづくりの精神、不良ゼロ品質、環境に配慮したサステナブルな生産を通じて、世界で最も信頼されるTier-1自動車部品パートナーを目指します。', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(42, 'company_profile', 1, 'ja', 'mission', '最先端の技術革新、徹底した品質管理、人材の育成、そして環境への調和を通じて、世界中の搭乗者の安全と快適な車内空間を提供し続けます。', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(43, 'company_profile', 1, 'zh', 'tagline', '承袭日本匠心精造，铸就卓越汽车安全', '2026-10-16 01:34:48', '2026-10-16 01:34:48'),
	(44, 'company_profile', 1, 'zh', 'short_description', '全球知名Tier-1汽车零部件制造商，专业生产方向盘、安全气囊系统及内外饰树脂零件，通过IATF 16949、ISO 14001及ISO 45001权威认证。', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(45, 'company_profile', 1, 'zh', 'about_text', '印度尼西亚日本塑胶有限公司（PT Nihon Plast Indonesia）坐落于西爪哇省卡拉旺工业区。依托日本母公司自1948年以来的深厚积淀，专注于为全球一线汽车品牌提供高品质方向盘、安全气囊和精密注塑零部件。', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(46, 'company_profile', 1, 'zh', 'vision', '以精益求精的日本制造精神、零缺陷品质承诺及绿色环保理念，成为全球汽车制造商最值得信赖的一级安全部件核心战略伙伴。', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(47, 'company_profile', 1, 'zh', 'mission', '依托先进工程制造、严格的国际质量体系及持续的人才发展，为全球驾乘人员筑牢生命安全防线，带来非凡座舱体验。', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(48, 'company_profile', 1, 'ko', 'tagline', '일본 모노즈쿠리 장인정신으로 완성하는 차량 안전과 정밀 공학', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(49, 'company_profile', 1, 'ko', 'short_description', 'IATF 16949, ISO 14001, ISO 45001 글로벌 인증을 획득한 스티어링 휠, 에어백 모듈 및 내외장 수지 부품 전문 글로벌 Tier-1 자동차 부품 기업.', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(50, 'company_profile', 1, 'ko', 'about_text', 'PT Nihon Plast Indonesia는 인도네시아 서자바주 카라왕 산업단지에 위치한 대표적인 글로벌 Tier-1 자동차 공급업체입니다. 1948년 창립된 일본 니혼플라스트의 독보적인 기술력을 바탕으로 세계 유수의 완성차 업체를 위한 안전 핵심 부품을 생산합니다.', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(51, 'company_profile', 1, 'ko', 'vision', '철저한 장인정신과 무결점 품질, 지속 가능한 친환경 제조를 선도하여 전 세계 완성차 고객이 가장 신뢰하는 Tier-1 파트너로 도약한다.', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(52, 'company_profile', 1, 'ko', 'mission', '최첨단 사출 성형 기술과 엄격한 품질 관리 체계, 인재 육성을 통하여 모든 운전자와 탑승자의 생명과 안전을 책임지는 최고의 부품을 공급한다.', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(53, 'page_banner', 1, 'en', 'page_title', 'PT Nihon Plast Indonesia', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(54, 'page_banner', 1, 'en', 'subtitle', 'Global Tier-1 Automotive Safety & Precision Resin Systems', '2026-10-16 01:34:49', '2026-10-16 01:34:49'),
	(55, 'page_banner', 1, 'ja', 'page_title', 'PT Nihon Plast Indonesia', '2026-10-16 01:34:50', '2026-10-16 01:34:50'),
	(56, 'page_banner', 1, 'ja', 'subtitle', 'グローバルTier-1自動車安全・高精度樹脂システム', '2026-10-16 01:34:50', '2026-10-16 01:34:50'),
	(57, 'page_banner', 1, 'zh', 'page_title', 'PT Nihon Plast Indonesia', '2026-10-16 01:34:50', '2026-10-16 01:34:50'),
	(58, 'page_banner', 1, 'zh', 'subtitle', '全球一级汽车安全与精密树脂制造系统', '2026-10-16 01:34:50', '2026-10-16 01:34:50'),
