	(74, 'products_resins', NULL, 'Polypropylene (PP-TD / PP-GF)', 'Door trims, cowl tops, consoles', NULL, 'bi-layers', NULL, NULL, NULL, 10, 1, '2026-10-14 09:27:40', '2026-10-14 09:27:40'),
